def choose_move(observation):
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [0, 0])
    env = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    def move_towards(target):
        dx = 0
        dy = 0
        if target is None:
            return [0,0]
        tx, ty = target
        dx = 0 if tx == sx else (1 if tx > sx else -1)
        dy = 0 if ty == sy else (1 if ty > sy else -1)
        return [dx, dy]

    # Pursuit and evasion logic
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = [ox, oy]
            return move_towards(target)
        else:
            corners = [
                [0, 0],
                [0, grid_height - 1],
                [grid_width - 1, 0],
                [grid_width - 1, grid_height - 1],
            ]
            target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
            return move_towards(target)

    # Territory control logic
    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells") 
            or observation.get("opponent_territory") 
            or []
        )
        if not targets:
            return [0, 0]
        closest = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(closest)

    # Resource collection logic
    resources = observation.get("resources") or []
    if resources:
        closest_resource = min(resources, key=lambda r: abs(r[0] - sx) + abs(r[1] - sy))
        return move_towards(closest_resource)
    else:
        # No resources, move toward opponent or center
        # Let's prefer moving towards the opponent if known
        if observation.get("opponent_position"):
            return move_towards([ox, oy])
        # Otherwise, stay in place
        return [0, 0]

